<style>
    .handover-title{margin:0 0 24px}.handover-title a{color:#7542a8;font-size:13px;text-decoration:none}.handover-title h1{font:800 25px 'Plus Jakarta Sans',sans-serif;margin:12px 0 6px;color:#292521}.handover-title p{font-size:13px;color:#827b75}
    .handover-grid{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(0,1fr);gap:20px;align-items:start}
    .handover-card{background:white;border:1px solid #ebe7e3;border-radius:16px;padding:22px;margin-bottom:16px;overflow-wrap:anywhere;color:#292521}
    .handover-card h2{font-size:17px;margin:0 0 14px}.handover-card h3{font-size:14px;margin:4px 0}.handover-card p,.handover-card small{font-size:13px;line-height:1.65;color:#827b75}
    .handover-heading,.handover-row{display:flex;justify-content:space-between;align-items:center;gap:12px}.handover-row{padding:14px 0;border-bottom:1px solid #ebe7e3;font-size:13px}.handover-row:last-child{border-bottom:0}
    .handover-badge{background:#f3eafb;color:#7542a8;border-radius:999px;padding:6px 11px;font-size:11px;font-weight:700;flex-shrink:0}.handover-info,.handover-error{padding:14px;border-radius:12px;background:#f3eafb;color:#65428a;margin:14px 0;font-size:13px;line-height:1.6}.handover-error{background:#fff1ef;color:#a43535}
    .handover-card form{margin-top:18px}.handover-card label{display:block;font-size:13px;font-weight:600;margin:12px 0 6px}.handover-card input:not([type=checkbox]){width:100%;padding:12px;border:1px solid #ded9d4;border-radius:10px;font:inherit}.handover-card .handover-agree{display:flex;align-items:flex-start;gap:9px;line-height:1.5}.handover-agree input{accent-color:#7542a8}
    .handover-btn{width:100%;display:block;padding:12px 16px;border:0;border-radius:999px;background:#7542a8;color:white;font:inherit;font-size:13px;font-weight:700;cursor:pointer;margin-top:12px}.handover-btn:hover{background:#643391}
    @media(max-width:800px){.handover-grid{grid-template-columns:1fr;gap:0}.handover-card{padding:16px}.handover-title h1{font-size:22px}}
</style>
